    24→  private static async resolveCallIntent(room: RoomInterface): Promise<Intent> {
    25→    const hasActiveCall = room.hasActiveRoomCall();
    26→    const isDirect = await room.isDirect();
    27→
    28→    if (hasActiveCall) {
    29→      return isDirect ? Intent.JoinExistingDm : Intent.JoinExisting;
    30→    }
    31→    return isDirect ? Intent.StartCallDm : Intent.StartCall;
    32→  }
