    34→  static async createWidgetSettings(roomId: string, room: RoomInterface) {
    35→    try {
    36→      const encryptionState = await room.latestEncryptionState();
    37→      const isEncrypted = encryptionState === EncryptionState.Encrypted;
    38→      const intent = await this.resolveCallIntent(room);
    39→
    40→      const options: VirtualElementCallWidgetProperties = {
    41→        elementCallUrl: "https://call.element.io/room",
    42→        widgetId: `element-call-${roomId}`,
    43→        fontScale: 1,
    44→        parentUrl: undefined,
    45→        font: undefined,
    46→        encryption: isEncrypted
    47→          ? new EncryptionSystem.PerParticipantKeys()
    48→          : new EncryptionSystem.Unencrypted(),
    49→        posthogApiHost: undefined,
    50→        posthogApiKey: undefined,
    51→        posthogUserId: undefined,
    52→        rageshakeSubmitUrl: undefined,
    53→        sentryDsn: undefined,
    54→        sentryEnvironment: undefined,
    55→      };
    56→
    57→      const config: VirtualElementCallWidgetConfig = {
    58→        hideHeader: true,
    59→        preload: false,
    60→        confineToRoom: true,
    61→        header: HeaderStyle.None,
    62→        appPrompt: false, // Hides "Open in App" prompt
