   112→  static createCapabilitiesProvider() {
   113→    const provider: WidgetCapabilitiesProvider = {
   114→      acquireCapabilities: (requestedCapabilities) => {
   115→        // Grant what the widget is requesting, not just the base permissions
   116→        // The widget needs state keys with _m.call suffix, but getElementCallRequiredPermissions
   117→        // only returns keys without the suffix
